using DocumentFormat.OpenXml.Packaging;using DocumentFormat.OpenXml.Wordprocessing;using System.Text;using System.Text.Encodings.Web;using System.IO.Compression;
namespace MyDoc.Services;
public interface IDocxImportService{Task<(bool Ok,string Html,string Error)>ConvertAsync(IFormFile?file,CancellationToken ct=default);}
public sealed class DocxImportService(IHtmlSafetyService safety):IDocxImportService{public async Task<(bool Ok,string Html,string Error)>ConvertAsync(IFormFile?f,CancellationToken ct=default){if(f is null||f.Length==0)return(false,"","Choose a non-empty .docx file.");if(f.Length>5_242_880)return(false,"","Word files must be 5 MB or smaller.");if(Path.GetExtension(f.FileName).ToLowerInvariant()!=".docx")return(false,"","Only .docx files are supported.");await using var ms=new MemoryStream();await f.CopyToAsync(ms,ct);if(ms.Length<4||ms.GetBuffer()[0]!=0x50||ms.GetBuffer()[1]!=0x4b)return(false,"","This is not a valid DOCX package.");try{ms.Position=0;using var zip=new ZipArchive(ms,ZipArchiveMode.Read,true);if(zip.Entries.Count>500||zip.Entries.Sum(e=>e.Length)>20_000_000||zip.GetEntry("word/document.xml") is null)return(false,"","The Word file is invalid or too complex.");ms.Position=0;using var word=WordprocessingDocument.Open(ms,false);var body=word.MainDocumentPart?.Document.Body;if(body is null)return(false,"","The Word document has no readable body.");var b=new StringBuilder();foreach(var p in body.Elements<Paragraph>()){var text=HtmlEncoder.Default.Encode(string.Concat(p.Descendants<Text>().Select(x=>x.Text)));if(string.IsNullOrWhiteSpace(text))continue;var runs=p.Elements<Run>();if(runs.Any(r=>r.RunProperties?.Bold is not null))text=$"<strong>{text}</strong>";if(runs.Any(r=>r.RunProperties?.Italic is not null))text=$"<em>{text}</em>";if(runs.Any(r=>r.RunProperties?.Underline is not null))text=$"<u>{text}</u>";var style=p.ParagraphProperties?.ParagraphStyleId?.Val?.Value??"";var tag=style.Contains("Heading1",StringComparison.OrdinalIgnoreCase)?"h1":style.Contains("Heading2",StringComparison.OrdinalIgnoreCase)?"h2":"p";b.Append($"<{tag}>{text}</{tag}>");}var html=safety.Sanitize(b.ToString());return html=="<p><br></p>"?(false,"","The Word document contains no supported text."):(true,html,"");}catch(Exception){return(false,"","The Word file is corrupt, encrypted, or unsupported.");}}}
